sp_widget.client_script:
api.controller = function($location) {
    var c = this;

    c.goBack = function() {
        $location.search('id', 'x_839216_public_0_my_requests');
    };

    c.getStatusClass = function(status) {
        if (!status) return 'label-default';
        var s = status.toLowerCase();
        if (s === 'approved') return 'label-success';
        if (s === 'in_progress' || s === 'in progress') return 'label-warning';
        if (s === 'rejected') return 'label-danger';
        if (s === 'submitted') return 'label-info';
        return 'label-default';
    };

    c.getPriorityClass = function(priority) {
        if (!priority) return 'label-default';
        var p = priority.toLowerCase();
        if (p === 'critical') return 'label-danger';
        if (p === 'high') return 'label-warning';
        if (p === 'medium') return 'label-info';
        return 'label-default';
    };

    c.getUrgencyClass = function(urgency) {
        if (!urgency) return 'label-default';
        var u = urgency.toLowerCase();
        if (u === 'critical') return 'label-danger';
        if (u === 'high') return 'label-warning';
        if (u === 'medium') return 'label-info';
        return 'label-default';
    };

    // Build progress steps based on current status
    c.buildProgressSteps = function() {
        var record = c.data.record;
        if (!record) return;

        var status = (record.u_status || '').toLowerCase();
        var isRejected = (status === 'rejected');

        var steps = [
            {id: 'submitted', label: 'Submitted', icon: 'glyphicon-edit', completed: false, active: false, rejected: false, pending: true},
            {id: 'in_progress', label: 'In Progress', icon: 'glyphicon-cog', completed: false, active: false, rejected: false, pending: true},
            {id: 'final', label: isRejected ? 'Rejected' : 'Approved', icon: isRejected ? 'glyphicon-remove' : 'glyphicon-ok', completed: false, active: false, rejected: false, pending: true}
        ];

        if (status === 'submitted') {
            steps[0].active = true;
            steps[0].pending = false;
        } else if (status === 'in_progress' || status === 'in progress') {
            steps[0].completed = true;
            steps[0].pending = false;
            steps[1].active = true;
            steps[1].pending = false;
        } else if (status === 'approved') {
            steps[0].completed = true;
            steps[0].pending = false;
            steps[1].completed = true;
            steps[1].pending = false;
            steps[2].completed = true;
            steps[2].pending = false;
        } else if (status === 'rejected') {
            steps[0].completed = true;
            steps[0].pending = false;
            steps[1].completed = true;
            steps[1].pending = false;
            steps[2].rejected = true;
            steps[2].pending = false;
        }

        c.progressSteps = steps;
    };

    c.buildProgressSteps();
};

sp_widget.css:
/* Header */
.sp-detail-header {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 24px;
    flex-wrap: wrap;
}
.sp-detail-number {
    font-size: 26px;
    font-weight: 700;
    color: #1a2b3c;
    margin: 0;
}
.sp-detail-panel {
    border: 1px solid #e8edf2;
    border-radius: 6px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04);
    margin-bottom: 20px;
}
.sp-detail-panel .panel-heading {
    background: #f8fafb;
    border-bottom: 1px solid #e8edf2;
}
.sp-field-value {
    font-size: 14px;
    color: #1a2b3c;
    margin: 4px 0 0;
    font-weight: 500;
}
.sp-notes-text {
    font-size: 14px;
    color: #3a4b5c;
    line-height: 1.6;
    white-space: pre-wrap;
}

/* Progress Indicator */
.sp-progress-container {
    background: #ffffff;
    border: 1px solid #e8edf2;
    border-radius: 8px;
    padding: 32px 24px;
    margin-bottom: 24px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04);
}
.sp-progress-bar {
    display: flex;
    justify-content: center;
    align-items: flex-start;
    gap: 0;
    position: relative;
}
.sp-progress-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    max-width: 200px;
}
.sp-progress-dot {
    width: 44px;
    height: 44px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 3px solid #d4dbe3;
    background: #ffffff;
    z-index: 2;
    transition: all 0.3s ease;
}
.sp-progress-dot .glyphicon {
    font-size: 16px;
    color: #a0aab4;
}
.sp-progress-label {
    margin-top: 10px;
    font-size: 12px;
    font-weight: 600;
    color: #8a9aab;
    text-align: center;
}
.sp-progress-connector {
    position: absolute;
    top: 22px;
    right: 50%;
    width: 100%;
    height: 3px;
    background: #e0e6ec;
    z-index: 1;
}

/* Step States */
.sp-step-completed .sp-progress-dot {
    background: #10b981;
    border-color: #10b981;
}
.sp-step-completed .sp-progress-dot .glyphicon {
    color: #ffffff;
}
.sp-step-completed .sp-progress-label {
    color: #10b981;
}
.sp-step-completed .sp-progress-connector,
.sp-connector-completed {
    background: #10b981;
}

.sp-step-active .sp-progress-dot {
    background: #0d8a8f;
    border-color: #0d8a8f;
    box-shadow: 0 0 0 4px rgba(13, 138, 143, 0.15);
}
.sp-step-active .sp-progress-dot .glyphicon {
    color: #ffffff;
}
.sp-step-active .sp-progress-label {
    color: #0d8a8f;
}

.sp-step-rejected .sp-progress-dot {
    background: #ef4444;
    border-color: #ef4444;
}
.sp-step-rejected .sp-progress-dot .glyphicon {
    color: #ffffff;
}
.sp-step-rejected .sp-progress-label {
    color: #ef4444;
}

.sp-step-pending .sp-progress-dot {
    background: #f8fafb;
    border-color: #d4dbe3;
}
.sp-step-pending .sp-progress-dot .glyphicon {
    color: #b0bac4;
}

/* Approval Banner */
.sp-approval-banner {
    background: #eff6ff;
    border: 1px solid #bfdbfe;
    border-radius: 6px;
    padding: 12px 18px;
    margin-bottom: 24px;
    font-size: 14px;
    color: #1e40af;
    display: flex;
    align-items: center;
    gap: 10px;
}
.sp-approval-banner .glyphicon {
    font-size: 16px;
}

/* Empty State */
.sp-empty-state {
    padding: 64px 24px;
}
.sp-empty-icon {
    font-size: 48px;
    margin-bottom: 16px;
    display: block;
    opacity: 0.35;
    color: #8a9aab;
}
.sp-empty-title {
    font-size: 18px;
    font-weight: 600;
    color: #1a2b3c;
    margin-bottom: 8px;
}

@media (max-width: 767px) {
    .sp-progress-container {
        padding: 24px 12px;
    }
    .sp-progress-dot {
        width: 36px;
        height: 36px;
    }
    .sp-progress-dot .glyphicon {
        font-size: 13px;
    }
    .sp-progress-connector {
        top: 18px;
    }
    .sp-progress-label {
        font-size: 11px;
    }
}

sp_widget.script:
(function() {
    data.record = null;
    data.notFound = false;

    var sysId = $sp.getParameter('sys_id');
    if (!sysId) {
        data.notFound = true;
        return;
    }

    var table = 'x_839216_public_0_health_service_request_v1';
    var gr = new GlideRecord(table);
    gr.setLimit(1);
    if (gr.get(sysId)) {
        data.record = {
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number') + '',
            u_citizen_name: gr.getValue('u_citizen_name') + '',
            u_email: gr.getValue('u_email') + '',
            u_phone_number: gr.getValue('u_phone_number') + '',
            u_request_type: gr.getDisplayValue('u_request_type') + '',
            u_urgency: gr.getDisplayValue('u_urgency') + '',
            u_priority: gr.getDisplayValue('u_priority') + '',
            u_status: gr.getDisplayValue('u_status') + '',
            u_approval_status: gr.getDisplayValue('u_approval_status') + '',
            assignment_group: gr.getDisplayValue('assignment_group') + '',
            u_appointment_date: gr.getDisplayValue('u_appointment_date') + '',
            u_purpose: gr.getValue('u_purpose') + '',
            u_notes: gr.getValue('u_notes') + '',
            sys_created_on: gr.getDisplayValue('sys_created_on') + '',
            sys_created_by: gr.getValue('sys_created_by') + '',
            opened_by: gr.getDisplayValue('opened_by') + ''
        };
    } else {
        data.notFound = true;
    }
})();
